namespace HRMS.Application.Common.Interfaces;

public interface IFileStorage
{
    // Saves a file and returns its relative path, e.g. "employees/5/photos/3f2a....jpg".
    // The file name is generated by the server; "folder" and "extension" are never user input.
    Task<string> SaveAsync(byte[] content, string folder, string extension);

    Task<byte[]?> ReadAsync(string relativePath);

    Task DeleteAsync(string relativePath);
}
